<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Avisos de pagamento</title><body style="font:16px system-ui;margin:30px"><h2>Notificações de pagamento</h2><p>Preferência deste usuário, válida nas telas do MK-AUTH. Novos pagamentos serão consultados a cada 5 segundos em abas visíveis. Nenhum pagamento antigo será anunciado ao abrir.</p><label><input type="checkbox" id="enabled" disabled> Exibir avisos de pagamento à esquerda</label><button id="save" disabled>Salvar</button><p id="status"></p><a href="cfg.php">Voltar</a><script>
let csrf;const enabled=document.getElementById('enabled'),save=document.getElementById('save'),status=document.getElementById('status');fetch('payment_events.php').then(r=>{if(!r.ok)throw Error('Serviço indisponível');return r.json();}).then(d=>{csrf=d.csrf;enabled.checked=d.enabled;enabled.disabled=save.disabled=false;}).catch(e=>status.textContent=e.message);save.onclick=async()=>{const r=await fetch('payment_events.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({csrf,enabled:enabled.checked?'1':'0'})});status.textContent=r.ok?'Preferência salva.':'Não foi possível salvar.';};</script></body></html>
